traceability.evidence:
Implementation and tests for branch-annotation rule are present and exercised:

1) Rule implementation
- File: src/rules/require-branch-annotation.ts
  - Declares ESLint rule `require-branch-annotation`:
    ```ts
    /**
     * Rule to enforce @story and @req annotations on significant code branches.
     *
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-BRANCH-DETECTION
     * @req REQ-CONFIGURABLE-SCOPE
     */
    import type { Rule } from "eslint";
    import {
      validateBranchTypes,
      reportMissingAnnotations,
    } from "../utils/branch-annotation-helpers";

    const rule: Rule.RuleModule = {
      meta: {
        type: "problem",
        docs: {
          description: "Require @story and @req annotations on code branches",
          recommended: "error",
        },
        fixable: "code",
        messages: {
          missingAnnotation: "Branch is missing required annotation: {{missing}}.",
        },
        schema: [ { /* branchTypes option schema */ } ],
      },
      create(context) {
        const branchTypesOrListener = validateBranchTypes(context);
        if (!Array.isArray(branchTypesOrListener)) {
          return branchTypesOrListener; // invalid config listener
        }
        const branchTypes = branchTypesOrListener;
        const storyFixCountRef = { count: 0 };
        const handlers: Rule.RuleListener = {};
        branchTypes.forEach((type) => {
          handlers[type] = function branchHandler(node) {
            if (type === "SwitchCase" && (node as any).test == null) {
              return; // default case: no annotation required
            }
            reportMissingAnnotations(context, node, storyFixCountRef);
          };
        });
        return handlers;
      },
    };
    export default rule;
    ```
  - References story 004 explicitly and requirements REQ-BRANCH-DETECTION and REQ-CONFIGURABLE-SCOPE.
  - Uses helper `validateBranchTypes` for configuration validation and `reportMissingAnnotations` for missing @story/@req detection.

- File: src/utils/branch-annotation-helpers.ts
  - Defines significant branch types and configuration validation:
    ```ts
    /**
     * Valid branch types for require-branch-annotation rule.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-SIGNIFICANCE-CRITERIA
     */
    export const DEFAULT_BRANCH_TYPES = [
      "IfStatement",
      "SwitchCase",
      "TryStatement",
      "CatchClause",
      "ForStatement",
      "ForOfStatement",
      "ForInStatement",
      "WhileStatement",
      "DoWhileStatement",
    ] as const;

    export type BranchType = (typeof DEFAULT_BRANCH_TYPES)[number];

    /**
     * @req REQ-CONFIGURABLE-SCOPE
     */
    export function validateBranchTypes(
      context: Rule.RuleContext,
    ): BranchType[] | Rule.RuleListener {
      const options: any = context.options[0] || {};
      if (Array.isArray(options.branchTypes)) {
        function isInvalidType(t: any): boolean {
          return !DEFAULT_BRANCH_TYPES.includes(t as BranchType);
        }
        const invalidTypes = options.branchTypes.filter(isInvalidType);
        if (invalidTypes.length > 0) {
          function ProgramHandler(node: any) {
            function reportInvalidType(t: any) {
              context.report({
                node,
                message: `Value "${t}" should be equal to one of the allowed values: ${DEFAULT_BRANCH_TYPES.join(", ")}`,
              });
            }
            invalidTypes.forEach(reportInvalidType);
          }
          return { Program: ProgramHandler };
        }
      }
      return Array.isArray(options.branchTypes)
        ? (options.branchTypes as BranchType[])
        : Array.from(DEFAULT_BRANCH_TYPES);
    }
    ```
  - Associates comments with branches and parses annotations:
    ```ts
    /** @req REQ-COMMENT-ASSOCIATION */
    export function gatherBranchCommentText(sourceCode, node): string {
      if (node.type === "SwitchCase") {
        const lines = sourceCode.lines;
        const startLine = node.loc.start.line;
        let i = startLine - PRE_COMMENT_OFFSET;
        const comments: string[] = [];
        while (i >= 0 && /^\s*(\/\/|\/\*)/.test(lines[i])) {
          comments.unshift(lines[i].trim());
          i--;
        }
        return comments.join(" ");
      }
      const comments = sourceCode.getCommentsBefore(node) || [];
      function commentToValue(c: any) { return c.value; }
      return comments.map(commentToValue).join(" ");
    }

    function getBranchAnnotationInfo(sourceCode, node) {
      const text = gatherBranchCommentText(sourceCode, node);
      const missingStory = !/@story\b/.test(text);
      const missingReq = !/@req\b/.test(text);
      const indent = sourceCode.lines[node.loc.start.line - 1].match(/^(\s*)/)?.[1] || "";
      const insertPos = sourceCode.getIndexFromLoc({ line: node.loc.start.line, column: 0 });
      return { missingStory, missingReq, indent, insertPos };
    }

    export function reportMissingAnnotations(context, node, storyFixCountRef) {
      const sourceCode = context.getSourceCode();
      const { missingStory, missingReq, indent, insertPos } = getBranchAnnotationInfo(sourceCode, node);
      const actions = [
        { missing: missingStory, fn: reportMissingStory, args: [context, node, { indent, insertPos, storyFixCountRef }] },
        { missing: missingReq, fn: reportMissingReq, args: [context, node, { indent, insertPos, missingStory }] },
      ];
      function processAction(item) {
        if (item.missing) {
          item.fn(...item.args);
        }
      }
      actions.forEach(processAction);
    }
    ```
  - Provides auto-fixers for missing `@story` and `@req` with clear default placeholders.

2) Rule integration into plugin config
- File: src/index.ts
  - Registers `require-branch-annotation` in rule list and configuration:
    ```ts
    const RULE_NAMES = [
      "require-story-annotation",
      "require-req-annotation",
      "require-branch-annotation",
      "valid-annotation-format",
      "valid-story-reference",
      "valid-req-reference",
      "prefer-implements-annotation",
    ] as const;

    const TRACEABILITY_RULE_SEVERITIES = {
      "traceability/require-story-annotation": "error",
      "traceability/require-req-annotation": "error",
      "traceability/require-branch-annotation": "error",
      // ...
    } as const;

    function createTraceabilityFlatConfig() {
      return {
        plugins: { traceability: {} },
        rules: { ...TRACEABILITY_RULE_SEVERITIES },
      };
    }

    const configs = {
      recommended: [createTraceabilityFlatConfig()],
      strict: [createTraceabilityFlatConfig()],
    };
    ```
  - Ensures the branch rule is part of recommended/strict presets in line with the story’s DoD.

3) Tests for branch-annotation behavior
- File: tests/rules/require-branch-annotation.test.ts
  - Tagged to story 004 and 007 with explicit requirements:
    ```ts
    /**
     * Tests for: docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md, docs/stories/007.0-DEV-ERROR-REPORTING.story.md
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
     * @req REQ-BRANCH-DETECTION
     * @req REQ-ERROR-SPECIFIC
     * @req REQ-ERROR-CONSISTENCY
     * @req REQ-ERROR-SUGGESTION
     */
    ```
  - Uses ESLint RuleTester with multiple valid scenarios covering different branch types and comment styles:
    - IfStatement, ForStatement, ForOfStatement, ForInStatement, WhileStatement, DoWhileStatement
    - Try/finally, catch blocks
    - SwitchCase (including inline and preceding comments)
    - Default case allowed without annotations
    - Block (`/* ... */`) and line (`// ...`) comments
    - Configurable branchTypes cases:
      ```ts
      {
        name: "[REQ-CONFIGURABLE-SCOPE] custom branchTypes ignores unlisted branch types",
        code: `switch (value) { case 'a': break; }`,
        options: [{ branchTypes: ["IfStatement"] }],
      },
      {
        name: "[REQ-CONFIGURABLE-SCOPE] custom branchTypes only enforce listed types",
        code: `// @story ...\n// @req REQ-BRANCH-DETECTION\nif (condition) {}`,
        options: [{ branchTypes: ["IfStatement", "SwitchCase"] }],
      },
      ```
  - Invalid tests verify detection and auto-fix behavior for missing annotations:
    - Missing both `@story` and `@req` on if/for/while/do-while/for-in/for-of/try-catch/switch-case
    - Missing only `@req` when `@story` is present, and vice versa
    - Switch-case with blank lines before the case (branch-comment association edge case)
    - Configurable scope enforcing only configured branch types:
      ```ts
      {
        name: "[REQ-CONFIGURABLE-SCOPE] missing annotations on configured branch type ForStatement",
        code: `for (let i = 0; i < 3; i++) {}`,
        options: [{ branchTypes: ["ForStatement"] }],
        output: `// @story .story.md\nfor (let i = 0; i < 3; i++) {}`,
        errors: [
          { messageId: "missingAnnotation", data: { missing: "@story" } },
          { messageId: "missingAnnotation", data: { missing: "@req" } },
        ],
      },
      ```
  - Invalid configuration behavior test:
